fixtures.src/orders/totals.py:
def compute_total(items: list[dict]) -> float:
    """Each item is {'price': float, 'qty': int, 'tax_rate': float}."""
    subtotal = 0.0
    for item in items:
        subtotal += item['price'] * item['qty']
    # BUG: tax is computed once on the whole subtotal using only the
    # last item's tax_rate, instead of per-item tax accumulation.
    if not items:
        return 0.0
    tax_rate = items[-1]['tax_rate']
    return round(subtotal * (1 + tax_rate), 2)

fixtures.src/metrics/normalize.py:
def normalize_value(x: float, lo: float, hi: float) -> float:
    if hi == lo:
        return 0.0
    return (x - lo) / (hi - lo)

fixtures.src/metrics/report.py:
